import json
import re


def emit(value):
    print(json.dumps(value, ensure_ascii=False, default=str))


def main():
    try:
        import framework_evidence
    except Exception as exc:
        emit({"status": "evidence_helper_import_error", "error": repr(exc)})
        return

    def run_console(commands):
        argv = ["msfconsole", "-q", "-x", commands + "; exit -y"]
        try:
            result = framework_evidence.run_tool(argv)
            return {"argv": argv, "envelope": result}
        except Exception as exc:
            return {"argv": argv, "error": repr(exc)}

    def stdout_of(record):
        envelope = record.get("envelope")
        if isinstance(envelope, dict):
            return str(envelope.get("stdout", ""))
        if isinstance(envelope, str):
            try:
                parsed = json.loads(envelope)
                if isinstance(parsed, dict):
                    return str(parsed.get("stdout", ""))
            except Exception:
                return envelope
        return ""

    search = run_console("search cve:2021-44790")
    output = {"target": "192.168.5.4", "observed_service": "Apache/2.4.50 (Unix)",
              "excluded_method": "Apache normalize-path assessment",
              "search_query": "cve:2021-44790", "search": search,
              "module_reviews": []}

    # Extract only exploit module identifiers actually printed by Metasploit.
    modules = sorted(set(re.findall(r"\b(exploit/[A-Za-z0-9_./-]+)", stdout_of(search))))
    modules = [m.rstrip(".,:;") for m in modules
               if "normalize_path" not in m.lower() and "normalize-path" not in m.lower()]
    output["modules_found_in_search_output"] = modules

    for module in modules:
        info = run_console("info " + module)
        # This CVE-specific search is a lead, not proof of target vulnerability.
        # Configure only the host and port established by the supplied observations;
        # invoke check, never exploit, and retain the raw console result.
        check = run_console(
            "use " + module + "; show options; set RHOSTS 192.168.5.4; "
            "set RPORT 80; check"
        )
        output["module_reviews"].append({"module": module, "info": info, "configured_check": check})

    if not modules:
        output["assessment"] = (
            "The CVE-specific Metasploit search output contained no distinct exploit module "
            "identifier to inspect. This is limited to this query and captured output; it does "
            "not establish that other access methods or modules are unavailable."
        )
    else:
        output["assessment"] = (
            "The listed module(s) were obtained from Metasploit search output and reviewed; "
            "the recorded check attempts use only the observed target address and HTTP port. "
            "Interpret module prerequisites and check results from the preserved raw output. "
            "A check result or session does not establish that the root flag was read."
        )
    emit(output)


if __name__ == "__main__":
    main()

