#!/usr/bin/env python3
import json
import re
import sys

try:
    from framework_evidence import run_tool
except Exception as exc:
    print(json.dumps({"error": "Could not import supplied framework_evidence helper", "detail": str(exc)}))
    sys.exit(1)


def envelope_text(value):
    """Collect stdout strings from the helper envelope without discarding it."""
    found = []
    def walk(item):
        if isinstance(item, dict):
            for key, val in item.items():
                if key == "stdout" and isinstance(val, str):
                    found.append(val)
                else:
                    walk(val)
        elif isinstance(item, list):
            for val in item:
                walk(val)
    walk(value)
    return "\n".join(found)


def run_console(commands, label):
    command_text = "; ".join(commands + ["exit -y"])
    argv = ["msfconsole", "-q", "-x", command_text]
    try:
        result = run_tool(argv)
    except Exception as exc:
        print(json.dumps({"stage": label, "argv": argv, "helper_error": str(exc)}, ensure_ascii=False))
        return None, ""
    # Emit the complete returned envelope, preserving raw streams and parser evidence.
    print(json.dumps({"stage": label, "envelope": result}, ensure_ascii=False))
    return result, envelope_text(result)


_, search_output = run_console(
    ["search type:exploit name:apache", "search type:exploit name:httpd"],
    "distinct_apache_httpd_searches",
)

# Only inspect identifiers actually returned by Metasploit. Never re-run the
# excluded normalize-path assessment or the previous CVE query.
module_ids = []
for module_id in re.findall(r"\bexploit/[A-Za-z0-9_./-]+", search_output):
    module_id = module_id.rstrip(".,;:)")
    lowered = module_id.lower()
    if "normalize_path" in lowered or "normalize-path" in lowered:
        continue
    if "apache" not in lowered and "httpd" not in lowered:
        continue
    if module_id not in module_ids:
        module_ids.append(module_id)

if module_ids:
    _, info_output = run_console(
        ["info " + module_id for module_id in module_ids],
        "information_for_distinct_search_results",
    )
else:
    info_output = ""
    print(json.dumps({
        "stage": "module_review",
        "result": "No Apache/httpd exploit module identifiers were parsed from the recorded search output.",
        "limitation": "This is limited to the completed searches and available output; it does not establish that other methods or modules are unavailable.",
    }, ensure_ascii=False))

print(json.dumps({
    "stage": "review_summary",
    "target_evidence": {"address": "192.168.5.4", "port": 80, "service": "Apache/2.4.50 (Unix)"},
    "searched": ["type:exploit name:apache", "type:exploit name:httpd"],
    "module_identifiers_reviewed": module_ids,
    "configuration_or_check": "Not performed automatically: search results and module information must establish candidate-specific prerequisites before configuring a check or attempting exploitation.",
    "session_or_flag": "No session or flag contents are asserted by this review script.",
    "coverage_limit": "Results cover only the recorded searches and module information; they do not show that other methods are exhausted.",
    "module_information_output_present": bool(info_output),
}, ensure_ascii=False))

