import json
import re
import sys
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit, urlunsplit

from framework_evidence import run_tool

ORIGIN = "http://192.168.5.4:80"
ROOT = ORIGIN + "/"
FAVICON = ORIGIN + "/favicon.ico"


class PageReferences(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.references = []
        self.metadata = []
        self.bases = []
        self.page_text = []
        self._in_title = False
        self.title = []

    def handle_starttag(self, tag, attrs):
        attrs = {str(k).lower(): (v or "") for k, v in attrs}
        tag = tag.lower()
        if tag == "base" and attrs.get("href"):
            self.bases.append(attrs["href"])
        if tag == "title":
            self._in_title = True

        if tag == "meta":
            item = {k: attrs[k] for k in ("name", "property", "http-equiv", "content") if attrs.get(k)}
            if item:
                self.metadata.append(item)
            if attrs.get("http-equiv", "").lower() == "refresh" and attrs.get("content"):
                match = re.search(r"(?i)(?:^|;)\s*url\s*=\s*['\"]?([^'\"]+)\s*['\"]?\s*$", attrs["content"])
                if match:
                    self.references.append({"tag": "meta-refresh", "attribute": "content-url", "value": match.group(1).strip()})

        if tag == "a" and attrs.get("href"):
            self.references.append({"tag": tag, "attribute": "href", "value": attrs["href"], "kind": "navigation"})
        elif tag == "area" and attrs.get("href"):
            self.references.append({"tag": tag, "attribute": "href", "value": attrs["href"], "kind": "navigation"})
        elif tag == "form" and attrs.get("action"):
            method = attrs.get("method", "get").lower()
            self.references.append({"tag": tag, "attribute": "action", "value": attrs["action"], "method": method, "kind": "form-action"})
        elif tag == "script" and attrs.get("src"):
            self.references.append({"tag": tag, "attribute": "src", "value": attrs["src"], "kind": "script"})
        elif tag in ("link", "iframe", "frame", "img", "source", "video", "audio", "embed", "object"):
            key = "data" if tag == "object" else "src" if tag in ("iframe", "frame", "img", "source", "video", "audio", "embed") else "href"
            value = attrs.get(key)
            if value:
                self.references.append({"tag": tag, "attribute": key, "value": value, "rel": attrs.get("rel", ""), "kind": "resource-or-link"})
        if tag == "link" and attrs.get("rel", "").lower() in ("manifest", "icon", "shortcut icon", "preload", "modulepreload"):
            # The href is already recorded above; annotate its application-relevant relation.
            if attrs.get("href"):
                self.references.append({"tag": tag, "attribute": "href", "value": attrs["href"], "rel": attrs.get("rel", ""), "kind": "declared-metadata-resource"})

    def handle_endtag(self, tag):
        if tag.lower() == "title":
            self._in_title = False

    def handle_data(self, data):
        if self._in_title:
            self.title.append(data)
        if data.strip():
            self.page_text.append(data.strip())


def tool_run(url):
    argv = ["curl", "-sS", "-D", "-", "--max-time", "20", "--", url]
    try:
        envelope = run_tool(argv)
    except Exception as exc:
        return {"requested_url": url, "argv": argv, "wrapper_error": str(exc), "status_code": None, "headers": [], "body_preview": ""}

    stdout = ""
    runs = envelope.get("tool_runs", []) if isinstance(envelope, dict) else []
    if runs and isinstance(runs[0], dict):
        stdout = runs[0].get("stdout") or ""
    if not isinstance(stdout, str):
        stdout = str(stdout)

    # curl -D - places response headers and body in the same stdout stream.
    # Retain the original envelope separately; this split is only for inspection.
    sep = "\r\n\r\n"
    pos = stdout.find(sep)
    if pos < 0:
        sep = "\n\n"
        pos = stdout.find(sep)
    header_block = stdout[:pos] if pos >= 0 else ""
    body = stdout[pos + len(sep):] if pos >= 0 else ""
    header_lines = header_block.splitlines()
    status_code = None
    for line in header_lines:
        match = re.match(r"^HTTP/\S+\s+(\d{3})", line.strip())
        if match:
            status_code = int(match.group(1))
    headers = [line for line in header_lines if not re.match(r"^HTTP/\S+\s+\d{3}", line.strip()) and line.strip()]
    body_bytes = body.encode("utf-8", "replace")
    return {
        "requested_url": url,
        "argv": argv,
        "status_code": status_code,
        "headers": headers,
        "body_preview": body[:1800],
        "body_utf8_length": len(body_bytes),
        "body_hex_prefix": body_bytes[:48].hex(),
        "tool_envelope": envelope,
    }


def canonical_url(base, value):
    value = (value or "").strip()
    if not value or value.startswith("#"):
        return None
    try:
        candidate = urljoin(base, value)
        parts = urlsplit(candidate)
        origin = urlsplit(ORIGIN)
        if parts.scheme.lower() not in ("http", "https"):
            return None
        if (parts.hostname or "").lower() != origin.hostname or parts.port != 80 or parts.username or parts.password:
            return None
        # Drop fragments: they never cause a distinct HTTP request.
        return urlunsplit((parts.scheme.lower(), parts.netloc.lower(), parts.path or "/", parts.query, ""))
    except (ValueError, TypeError):
        return None


def main():
    results = []
    root_result = tool_run(ROOT)
    results.append(root_result)

    root_text = ""
    root_refs = []
    page_summary = {"title": "", "metadata": [], "visible_text_preview": "", "base_hrefs": []}
    if root_result.get("status_code") is not None:
        body = root_result.get("body_preview", "")
        parser = PageReferences()
        try:
            parser.feed(body)
            parser.close()
            root_refs = parser.references
            page_summary = {
                "title": " ".join(" ".join(parser.title).split()),
                "metadata": parser.metadata,
                "visible_text_preview": " ".join(parser.page_text)[:1800],
                "base_hrefs": parser.bases,
            }
            root_text = body
        except Exception as exc:
            page_summary["parser_error"] = str(exc)

    # Always inspect the named favicon resource, even if the root request failed.
    results.append(tool_run(FAVICON))

    reference_base = ROOT
    for base_value in page_summary.get("base_hrefs", []):
        resolved_base = canonical_url(ROOT, base_value)
        if resolved_base:
            reference_base = resolved_base
            break

    checked = {ROOT, FAVICON}
    reference_records = []
    for ref in root_refs:
        target = canonical_url(reference_base, ref.get("value", ""))
        record = dict(ref)
        record["resolved_same_origin_url"] = target
        if not target:
            record["action"] = "not-followed: not a valid same-origin HTTP reference"
        elif ref.get("tag") == "form" and ref.get("method", "get").lower() != "get":
            record["action"] = "not-followed: non-GET form action; no form submitted"
        elif target in checked:
            record["action"] = "not-followed: URL already requested"
        else:
            checked.add(target)
            record["action"] = "followed once with GET"
            results.append(tool_run(target))
        reference_records.append(record)

    print(json.dumps({
        "target_origin": ORIGIN,
        "requests": results,
        "root_page_inspection": page_summary,
        "root_declared_references": reference_records,
        "coverage_limitations": [
            "Only the root response, favicon, and references declared directly by the root page were requested; fetched resources were not recursively parsed.",
            "Only same-origin HTTP references on port 80 were followed. Non-GET form actions were recorded but not requested, and no forms were submitted.",
            "Status, headers, and body evidence are available only when returned by the request tool; errors or missing responses do not establish that other routes are unavailable."
        ]
    }, ensure_ascii=True))


if __name__ == "__main__":
    main()

