import json
import re
import sys

try:
    import framework_evidence
except Exception as exc:
    print(json.dumps({"error": "Could not import framework_evidence", "detail": str(exc)}))
    raise SystemExit(1)

search_argv = [
    "msfconsole",
    "-q",
    "-x",
    "search type:exploit name:apache; exit",
]

try:
    search_envelope = framework_evidence.run_tool(search_argv)
except Exception as exc:
    print(json.dumps({"error": "Metasploit search invocation failed", "argv": search_argv, "detail": str(exc)}))
    raise SystemExit(1)

# Keep the returned envelope intact. Parse only module identifiers present in its raw output.
def collect_stdout(envelope):
    if not isinstance(envelope, dict):
        return ""
    pieces = []
    for run in envelope.get("tool_runs", []):
        if isinstance(run, dict):
            pieces.append(str(run.get("stdout", "")))
    return "\n".join(pieces)

search_stdout = collect_stdout(search_envelope)
module_ids = sorted(set(re.findall(r"\bexploit/[A-Za-z0-9_./-]+", search_stdout)))
excluded = {
    "exploit/multi/http/apache_normalize_path",
    "exploit/multi/http/apache_mod_cgi_bash_env_exec",
}
candidates = [
    module_id for module_id in module_ids
    if "/http/" in module_id.lower()
    and "apache" in module_id.lower()
    and module_id not in excluded
]

info_envelope = None
info_argv = None
if candidates:
    # Inspect requirements only; do not set options or invoke an exploit/check.
    commands = ["info " + module_id for module_id in candidates]
    commands.append("exit")
    info_argv = ["msfconsole", "-q", "-x", "; ".join(commands)]
    try:
        info_envelope = framework_evidence.run_tool(info_argv)
    except Exception as exc:
        info_envelope = {"invocation_error": str(exc), "argv": info_argv}

result = {
    "target_evidence_considered": {
        "target": "192.168.5.4:80",
        "observed_server": "Apache/2.4.50 (Unix)",
        "observed_root": "HTTP 200; plain default 'It works!' page",
        "observed_application_references": "None found in the inspected root page",
        "coverage_limitations": [
            "The supplied inspection covered the root page, favicon, and root-declared references; it was not a recursive route crawl.",
            "The earlier Metasploit assessment inspected a CGI-oriented module, but the supplied HTTP observations do not establish a CGI script.",
            "The Apache normalize-path configuration was already attempted and is not repeated here.",
        ],
    },
    "search_argv": search_argv,
    "search_envelope": search_envelope,
    "parsed_distinct_apache_http_candidates": candidates,
    "excluded_previously_assessed_modules": sorted(excluded),
    "module_info_argv": info_argv,
    "module_info_envelope": info_envelope,
    "assessment": (
        "Candidate requirements were inspected where distinct Apache HTTP module identifiers were present in the search output. "
        "No module was configured or attempted because the supplied evidence establishes no application or endpoint prerequisite beyond a default Apache page. "
        "An empty or incomplete search/parse result does not establish that other methods are unavailable."
    ),
