    except Exception as exc:
        print(json.dumps({"status": "serialization_error", "error": str(exc)}))


def main():
    try:
        helper = importlib.import_module("framework_evidence")
    except Exception as exc:
        emit({
            "status": "helper_unavailable",
            "evidence_ref": EVIDENCE_REF,
            "error": str(exc),
        })
        return 1

    for name in CANDIDATES:
