import ast
import hashlib
import json
import os
import re
import tempfile

TARGET = "http://192.168.5.4:80"
SCRIPT_DIR = "/root/scripts"


def valid_path(value):
    if not isinstance(value, str) or not value.startswith("/"):
        return False
    if any(ord(ch) < 32 or ord(ch) == 127 for ch in value):
        return False
    if "\\" in value:
        return False
    if any(part == ".." for part in value.split("/")):
        return False
    return True


def find_selected_paths():
    candidates = []
    try:
        names = os.listdir(SCRIPT_DIR)
    except OSError as exc:
        return None, None, "cannot inspect generated probe scripts: " + str(exc)

    for name in names:
        if not name.endswith(".py"):
            continue
        lowered = name.lower()
        if not any(token in lowered for token in ("probe", "http", "path", "record")):
            continue
        source_path = os.path.join(SCRIPT_DIR, name)
        try:
            with open(source_path, "r", encoding="utf-8", errors="replace") as handle:
                source = handle.read()
            tree = ast.parse(source, filename=source_path)
        except (OSError, SyntaxError, UnicodeError):
            continue

        for node in ast.walk(tree):
            if not isinstance(node, (ast.List, ast.Tuple)):
                continue
            try:
                value = ast.literal_eval(node)
            except (ValueError, TypeError, SyntaxError):
                continue
            if not isinstance(value, (list, tuple)):
                continue
            paths = list(value)
            if len(paths) != 12 or not all(valid_path(item) for item in paths):
                continue
            if len(set(paths)) != 12:
                continue
            # Prefer the repeat-probe input, then the original additional-path probe.
            score = 0
            if "repeat" in lowered or "selected" in lowered:
                score += 20
            if "additional" in lowered or "probe" in lowered:
                score += 10
            candidates.append((score, name, paths))

    if not candidates:
        return None, None, "no generated probe source exposed an exact list of 12 distinct safe paths"
    candidates.sort(key=lambda item: (-item[0], item[1]))
    _, name, paths = candidates[0]
    return paths, os.path.join(SCRIPT_DIR, name), None


def envelope_value(envelope, key, default=""):
    if isinstance(envelope, dict):
        value = envelope.get(key, default)
        return value if isinstance(value, str) else str(value)
    return default


def relevant_headers(raw):
    wanted = {
        "server", "content-type", "content-length", "location", "allow",
        "www-authenticate", "x-powered-by", "last-modified", "cache-control"
    }
    blocks = re.split(r"(?m)(?=^HTTP/\S+\s+\d{3})", raw)
    selected = {}
    for block in blocks:
        if not re.match(r"^HTTP/\S+\s+\d{3}", block):
            continue
        current = {}
        for line in block.splitlines()[1:]:
            if not line.strip():
                break
            if ":" not in line:
                continue
            key, value = line.split(":", 1)
            key = key.strip().lower()
            if key in wanted:
                current.setdefault(key, []).append(value.strip())
        selected = current
    return selected


def main():
    paths, source_path, error = find_selected_paths()
    if error:
        print(json.dumps({"status": "input_unavailable", "detail": error, "requests_made": 0}, separators=(",", ":")))
        return

    try:
        import framework_evidence
    except Exception as exc:
        print(json.dumps({"status": "execution_prerequisite_unavailable", "detail": "cannot import supplied framework_evidence helper: " + str(exc), "requests_made": 0}, separators=(",", ":")))
        return

    print(json.dumps({"status": "starting", "path_source": source_path, "path_count": len(paths)}, separators=(",", ":")))
    for path in paths:
        url = TARGET + path
        tmp_name = None
        try:
            with tempfile.NamedTemporaryFile(prefix="http_body_", delete=False) as tmp:
                tmp_name = tmp.name
            argv = [
                "curl", "--silent", "--show-error", "--max-time", "12",
                "--dump-header", "-", "--output", tmp_name,
                "--write-out", "\n__HTTP_STATUS__:%{http_code}\n", url
            ]
            envelope = framework_evidence.run_tool(argv)
            if isinstance(envelope, str):
                try:
                    envelope = json.loads(envelope)
                except json.JSONDecodeError:
                    envelope = {"raw_result": envelope}

            raw_stdout = envelope_value(envelope, "stdout")
            raw_stderr = envelope_value(envelope, "stderr")
            match = re.search(r"__HTTP_STATUS__:(\d{3})", raw_stdout)
            status = int(match.group(1)) if match else None
            exit_code = envelope.get("exit_code") if isinstance(envelope, dict) else None
            completed = exit_code == 0 and status is not None and status != 0

            try:
                with open(tmp_name, "rb") as body_file:
                    body = body_file.read()
            except OSError:
                body = b""

            snippet = body[:120].decode("utf-8", errors="replace")
            snippet = " ".join(snippet.split())
            record = {
                "request": {"method": "GET", "url": url},
                "completion": "completed" if completed else "failed",
                "http_status": status,
                "relevant_response_headers": relevant_headers(raw_stdout),
                "body_indicator": {
                    "bytes": len(body),
                    "sha256": hashlib.sha256(body).hexdigest(),
                    "preview": snippet
                },
                "failure_detail": None if completed else {
                    "exit_code": exit_code,
                    "stderr": raw_stderr,
                    "note": "A non-2xx HTTP status is a completed HTTP response, not a request failure."
                },
                "tool_evidence": envelope
            }
            print(json.dumps(record, ensure_ascii=False, separators=(",", ":"), default=str))
        except Exception as exc:
            print(json.dumps({
                "request": {"method": "GET", "url": url},
                "completion": "failed",
                "http_status": None,
                "relevant_response_headers": {},
                "body_indicator": None,
                "failure_detail": str(exc)
            }, ensure_ascii=False, separators=(",", ":")))
        finally:
            if tmp_name:
                try:
                    os.unlink(tmp_name)
                except OSError:
                    pass


if __name__ == "__main__":
    main()

