import ast
import hashlib
import json
import os
import urllib.error
import urllib.request

TARGET = "http://192.168.5.4:80"
SOURCE_DIR = "/root/scripts"


class NoRedirectHandler(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def find_paths():
    candidates = []
    try:
        filenames = os.listdir(SOURCE_DIR)
    except OSError as exc:
        raise RuntimeError("cannot inspect prior generated probe sources: " + str(exc))

    for filename in filenames:
        if not filename.endswith(".py") or filename == os.path.basename(__file__):
            continue
        source_path = os.path.join(SOURCE_DIR, filename)
        try:
            with open(source_path, "r", encoding="utf-8") as stream:
                source = stream.read()
            tree = ast.parse(source, filename=source_path)
        except (OSError, UnicodeError, SyntaxError):
            continue

        for node in ast.walk(tree):
            if not isinstance(node, (ast.List, ast.Tuple)) or len(node.elts) != 12:
                continue
            values = []
            for item in node.elts:
                if not isinstance(item, ast.Constant) or not isinstance(item.value, str):
                    break
                values.append(item.value)
            if len(values) != 12 or any(not value.startswith("/") for value in values):
                continue
            if len(set(values)) != 12:
                continue
            score = 0
            lower_name = filename.lower()
            if "probe" in lower_name or "path" in lower_name or "http" in lower_name:
                score += 2
            if "/cgi-bin/test-cgi" in source:
                score += 3
            candidates.append((score, filename, values))

    if not candidates:
        raise RuntimeError("no prior generated probe source containing the exact 12 selected paths was found")
    candidates.sort(key=lambda item: (-item[0], item[1]))
    best = candidates[0]
    tied = [item for item in candidates if item[0] == best[0] and item[2] != best[2]]
    if tied:
        raise RuntimeError("multiple prior probe sources contain different equally ranked 12-path lists")
    return best[1], best[2]


def body_indicator(response):
    sample = response.read(512)
    content_type = response.headers.get("Content-Type", "")
    text = sample.decode("utf-8", errors="replace")
    text = " ".join(text.split())
    if len(text) > 100:
        text = text[:100] + "…"
    return {
        "sampled_bytes": len(sample),
        "sample_sha256": hashlib.sha256(sample).hexdigest(),
        "snippet": text,
        "sample_limit": 512,
        "content_type": content_type,
    }


def main():
    try:
        source_name, paths = find_paths()
    except RuntimeError as exc:
        print(json.dumps({"status": "incomplete", "error": str(exc)}, separators=(",", ":")))
        return

    opener = urllib.request.build_opener(NoRedirectHandler())
    records = []
    selected_headers = (
        "Server", "Content-Type", "Content-Length", "Location",
        "Allow", "WWW-Authenticate", "Last-Modified", "Cache-Control",
    )
    for path in paths:
        url = TARGET + path
        record = {"url": url}
        request = urllib.request.Request(url, method="GET", headers={"User-Agent": "path-record-check/1.0"})
        try:
            response = opener.open(request, timeout=10)
        except urllib.error.HTTPError as exc:
            response = exc
        except Exception as exc:
            record.update({"completion": "request_failure", "error": type(exc).__name__ + ": " + str(exc)})
            records.append(record)
            continue

        try:
            record["completion"] = "http_response"
            record["status"] = response.getcode()
            record["headers"] = {
                name: response.headers.get(name)
                for name in selected_headers
                if response.headers.get(name) is not None
            }
            try:
                record["body"] = body_indicator(response)
            except Exception as exc:
                record["body_error"] = type(exc).__name__ + ": " + str(exc)
        finally:
            response.close()
        records.append(record)

    print(json.dumps({
        "status": "completed",
        "target": TARGET,
        "path_source": source_name,
        "record_count": len(records),
        "records": records,
    }, ensure_ascii=False, separators=(",", ":")))


if __name__ == "__main__":
    main()

