import json
import re

from framework_evidence import run_tool

HOST = "192.168.5.4:80"
PATHS = [
    "/server-status",
    "/server-info",
    "/cgi-bin/",
    "/cgi-bin/test-cgi",
    "/cgi-bin/printenv",
    "/cgi-bin/status",
    "/manual/",
    "/icons/",
    "/phpinfo.php",
    "/index.cgi",
    "/login",
    "/admin",
]


def tool_streams(envelope):
    """Return available raw streams from the helper envelope without replacing it."""
    streams = []
    if isinstance(envelope, dict):
        for run in envelope.get("tool_runs", []):
            if isinstance(run, dict):
                streams.append((run.get("stdout", ""), run.get("stderr", "")))
    return streams


def response_details(stdout):
    """Extract a compact display from curl's raw header-and-body output."""
    if not stdout:
        return None, []
    status_lines = re.findall(r"(?m)^HTTP/\S+\s+\d{3}[^\r\n]*", stdout)
    status_line = status_lines[-1] if status_lines else None

    # Use the final header block if an interim response was returned.
    blocks = re.split(r"\r?\n\r?\n", stdout)
    header_block = ""
    if status_line:
        for block in blocks:
            if status_line in block:
                header_block = block
    selected_headers = []
    for line in header_block.splitlines()[1:]:
        if ":" not in line:
            continue
        name, value = line.split(":", 1)
        if name.strip().lower() in {"server", "content-type", "content-length", "location", "last-modified"}:
            selected_headers.append(f"{name.strip()}: {value.strip()}")

    body = blocks[-1].strip() if len(blocks) > 1 else ""
    # Keep the displayed excerpt concise; the complete raw stream remains in tool_result.
    body_excerpt = re.sub(r"\s+", " ", body)[:240] if body else ""
    if body_excerpt:
        selected_headers.append("body_excerpt: " + body_excerpt)
    return status_line, selected_headers


for path in PATHS:
    url = f"http://{HOST}{path}"
    argv = ["curl", "--silent", "--show-error", "--include", "--max-time", "12", url]
    try:
        envelope = run_tool(argv)
        streams = tool_streams(envelope)
        stdout = "\n".join(item[0] for item in streams if item[0])
        stderr = "\n".join(item[1] for item in streams if item[1])
        status_line, details = response_details(stdout)
        has_status = status_line is not None
        record = {
            "url": url,
            "request_completed": has_status,
            "http_status_line": status_line,
            "response_details": details,
        }
        if not has_status:
            record["request_failure"] = stderr or "No HTTP status was present in the tool response."
        output = {"record": record, "tool_result": envelope}
    except Exception as exc:
        output = {
            "record": {
                "url": url,
                "request_completed": False,
                "http_status_line": None,
                "response_details": [],
                "request_failure": f"Tool invocation failed: {type(exc).__name__}: {exc}",
            },
            "tool_result": None,
        }
    print(json.dumps(output, ensure_ascii=False, separators=(",", ":")))

