import json
import os
from pathlib import Path
import sys

ARTIFACT = "llm_inputs/7234b6a9c4759419fa56f5007cb3d74e558b5c435149a73696823a2df1031510.json"
TRAVERSAL_MARKERS = (
    "traversal", "%2e", "%252e", "../", "..%", "normalize_path",
    "path-traversal", "apache"
)


def candidate_paths():
    rel = Path(ARTIFACT)
    seen = set()
    candidates = []

    def add(path):
        try:
            key = str(path.resolve(strict=False))
        except OSError:
            key = str(path)
        if key not in seen:
            seen.add(key)
            candidates.append(Path(key))

    cwd = Path.cwd()
    add(cwd / rel)
    for parent in list(cwd.parents)[:5]:
        add(parent / rel)
    add(Path("/root") / rel)
    add(Path("/workspace") / rel)
    add(Path("/app") / rel)
    return candidates


def record_text(value):
    try:
        return json.dumps(value, ensure_ascii=False, sort_keys=True)
    except (TypeError, ValueError):
        return repr(value)


def main():
    paths = candidate_paths()
    source = next((p for p in paths if p.is_file()), None)
    if source is None:
        print(json.dumps({
            "status": "source_not_found",
            "artifact": ARTIFACT,
            "checked_paths": [str(p) for p in paths],
            "errors": [
                {"path": str(p), "error": "not a readable regular file"}
                for p in paths
            ],
            "finding": "The full source could not be checked; request details remain unknown."
        }, ensure_ascii=False, indent=2))
        return 0

    try:
        with source.open("r", encoding="utf-8") as handle:
            document = json.load(handle)
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        print(json.dumps({
            "status": "source_read_or_parse_error",
            "source": str(source),
            "error_type": type(exc).__name__,
            "error": str(exc),
            "finding": "No request details were recovered from this source."
        }, ensure_ascii=False, indent=2))
        return 0

    prior = document.get("prior_observations", document)
    history = prior.get("history", []) if isinstance(prior, dict) else []
    if not isinstance(history, list):
        print(json.dumps({
            "status": "unexpected_record_shape",
            "source": str(source),
            "prior_observations_type": type(prior).__name__,
            "history_type": type(history).__name__,
            "finding": "The expected prior-observation history was not available in this shape."
        }, ensure_ascii=False, indent=2))
        return 0

    matched = []
    for index, entry in enumerate(history):
        text = record_text(entry).casefold()
        has_flag = "flag.txt" in text
        has_traversal = any(marker in text for marker in TRAVERSAL_MARKERS)
        if has_flag and has_traversal:
            matched.append({"history_index": index, "record": entry})

    print(json.dumps({
        "status": "source_checked",
        "source": str(source),
        "history_entries_examined": len(history),
        "matching_entry_count": len(matched),
        "match_criteria": "History entry contains flag.txt and at least one traversal-related marker.",
        "matching_history_entries": matched,
        "coverage_note": (
            "Entries are shown in full. Matching is a retrieval aid, not proof that these "
            "are the only related records; inspect the returned records and any referenced "
            "source material before treating the five representations as recovered."
        )
    }, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    sys.exit(main())

