import json
import os
from pathlib import Path

ARTIFACT = "llm_inputs/0acd47ad9e03dcc9fc19a3ad0c581ac834fd15f1538bdb0f10f712b031b1eacf.json"
BASENAME = os.path.basename(ARTIFACT)
SKIP_DIRS = {"/proc", "/sys", "/dev", "/run", "/usr", "/lib", "/lib64", "/bin", "/sbin"}
TERMS = ("traversal", "flag.txt", "%2e", "apache_normalize", "apache 2.4.50", "apache/2.4.50")


def candidate_paths():
    seen = set()
    for root in ("/root/scripts", "/root", "/", "/workspace", "/app", "/tmp", "/mnt", "/opt", "/var", "/home"):
        path = os.path.join(root, ARTIFACT)
        if path not in seen:
            seen.add(path)
            yield path


def locate_artifact():
    checked = []
    for path in candidate_paths():
        if path in checked:
            continue
        checked.append(path)
        try:
            if os.path.isfile(path) and os.access(path, os.R_OK):
                return path, checked, []
        except OSError:
            pass

    walk_errors = []
    roots = ("/root", "/workspace", "/app", "/tmp", "/mnt", "/opt", "/var", "/home", "/")
    visited = set()
    for root in roots:
        if root in visited or not os.path.isdir(root):
            continue
        visited.add(root)
        for current, dirs, files in os.walk(root, topdown=True, onerror=lambda e: walk_errors.append(str(e))):
            dirs[:] = [d for d in dirs if os.path.join(current, d) not in SKIP_DIRS]
            if current == "/":
                dirs[:] = [d for d in dirs if "/" + d not in SKIP_DIRS]
            if BASENAME in files:
                found = os.path.join(current, BASENAME)
                try:
                    if os.path.isfile(found) and os.access(found, os.R_OK):
                        return found, checked, walk_errors
                except OSError as exc:
                    walk_errors.append(f"{found}: {exc}")
    return None, checked, walk_errors


def collect_matches(value, path, matches, seen_strings, depth=0):
    if depth > 40:
        return
    if isinstance(value, dict):
        for key, child in value.items():
            collect_matches(child, f"{path}[{json.dumps(str(key), ensure_ascii=False)}]", matches, seen_strings, depth + 1)
    elif isinstance(value, list):
        for index, child in enumerate(value):
            collect_matches(child, f"{path}[{index}]", matches, seen_strings, depth + 1)
    elif isinstance(value, str):
        text = value
        if any(term in text.lower() for term in TERMS):
            signature = (path, text)
            if signature not in seen_strings:
                seen_strings.add(signature)
                matches.append({"json_path": path, "text": text})
        stripped = text.lstrip()
        if len(text) <= 8_000_000 and stripped.startswith(("{", "[", "\"")):
            try:
                decoded = json.loads(text)
            except (json.JSONDecodeError, RecursionError):
                return
            if isinstance(decoded, (dict, list)):
                collect_matches(decoded, path + "<decoded_json>", matches, seen_strings, depth + 1)


def main():
    found, checked, walk_errors = locate_artifact()
    result = {
        "artifact": ARTIFACT,
        "status": "source_not_found",
        "checked_direct_paths": checked,
        "walk_errors": walk_errors,
        "finding": "The archived original-input source was not located; request details remain unknown.",
    }
    if found is not None:
        result.update({"source_path": found, "status": "read_error"})
        try:
            raw = Path(found).read_bytes()
            result["bytes_read"] = len(raw)
            result["sha256"] = __import__("hashlib").sha256(raw).hexdigest()
            try:
                document = json.loads(raw)
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                result["status"] = "parse_error"
                result["error"] = str(exc)
            else:
                matches = []
                collect_matches(document, "$", matches, set())
                result["status"] = "read_and_parsed"
                result["matching_text_count"] = len(matches)
                result["matching_text"] = matches
                result["finding"] = "Matching source text is reported verbatim with JSON paths; verify which entries contain the five requests and outcomes. An empty match list does not establish that omitted or differently worded records are absent."
        except OSError as exc:
            result["error"] = f"{type(exc).__name__}: {exc}"
    print(json.dumps(result, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

