import json
import os
import sys

ARTIFACT = "2408f179e7ac5cdad73180a0679e9327f6330e9f731e2baa555104bdcdc805a2.json"
SKIP_DIRS = {"proc", "sys", "dev", "run"}
ROOTS = ["/root", "/workspace", "/app", "/tmp", "/var", "/home", "/mnt", "/opt", "/"]


def locate_artifact():
    checked = set()
    errors = []
    for root in ROOTS:
        if root in checked or not os.path.isdir(root):
            continue
        checked.add(root)
        for current, dirs, files in os.walk(root, topdown=True, onerror=lambda exc: errors.append(str(exc))):
            dirs[:] = [name for name in dirs if name not in SKIP_DIRS]
            if ARTIFACT in files:
                candidate = os.path.join(current, ARTIFACT)
                if os.path.isfile(candidate) and os.access(candidate, os.R_OK):
                    return candidate, errors
    return None, errors


def walk_records(value, pointer="$", seen=None):
    if seen is None:
        seen = set()
    if isinstance(value, dict):
        marker = id(value)
        if marker in seen:
            return
        seen.add(marker)
        goal = value.get("goal")
        execution = value.get("execution_result")
        if isinstance(goal, str) and isinstance(execution, dict):
            text = goal.lower()
            result_text = json.dumps(execution, ensure_ascii=False).lower()
            relevant = ("apache" in text and "travers" in text) or (
                "flag.txt" in text and ("request" in text or "prior" in text)
            ) or ("apache" in result_text and "travers" in result_text and "request" in text)
            if relevant:
                yield {
                    "source_pointer": pointer,
                    "node_id": value.get("node_id"),
                    "goal": goal,
                    "execution_result": execution,
                }
        for key, child in value.items():
            yield from walk_records(child, pointer + "." + str(key), seen)
    elif isinstance(value, list):
        for index, child in enumerate(value):
            yield from walk_records(child, pointer + "[" + str(index) + "]", seen)


def main():
    artifact_path, search_errors = locate_artifact()
    if artifact_path is None:
        print(json.dumps({
            "status": "source_not_found",
            "artifact": "llm_inputs/" + ARTIFACT,
            "search_roots": ROOTS,
            "walk_errors": search_errors,
            "finding": "The exact archived artifact was not located; prior request details remain unknown."
