import json
import os
from pathlib import Path

ARTIFACT = "ba39dc4699b8987b515b36f464990ea51071a2949200fbd56d7b24b3f8f583f3.json"
ROOTS = ["/root", "/workspace", "/app", "/tmp", "/var", "/home", "/mnt", "/opt"]
DIRECT = [
    f"llm_inputs/{ARTIFACT}",
    f"/root/scripts/llm_inputs/{ARTIFACT}",
    f"/root/llm_inputs/{ARTIFACT}",
    f"/llm_inputs/{ARTIFACT}",
    f"/workspace/llm_inputs/{ARTIFACT}",
    f"/app/llm_inputs/{ARTIFACT}",
]


def find_artifact():
    found = []
    checked = []
    for raw in DIRECT:
        path = Path(raw)
        checked.append(str(path))
        try:
            if path.is_file() and os.access(path, os.R_OK):
                found.append(str(path.resolve()))
        except OSError:
            pass
    for root in ROOTS:
        if not os.path.isdir(root):
            continue
        for current, dirs, files in os.walk(root, topdown=True, onerror=lambda _e: None):
            dirs[:] = [d for d in dirs if d not in {"proc", "sys", "dev", "run", ".git", "node_modules"}]
            if ARTIFACT in files:
                candidate = os.path.join(current, ARTIFACT)
                checked.append(candidate)
                try:
                    if os.path.isfile(candidate) and os.access(candidate, os.R_OK):
                        found.append(os.path.realpath(candidate))
                except OSError:
                    pass
    return sorted(set(found)), checked


def walk_records(value, path="$", seen=None):
    if seen is None:
        seen = set()
    if isinstance(value, dict):
        marker = id(value)
        if marker in seen:
            return
        seen.add(marker)
        yield path, value
        for key, child in value.items():
            yield from walk_records(child, f"{path}[{json.dumps(str(key))}]", seen)
    elif isinstance(value, list):
        marker = id(value)
        if marker in seen:
            return
        seen.add(marker)
        for index, child in enumerate(value):
            yield from walk_records(child, f"{path}[{index}]", seen)


def main():
    paths, checked = find_artifact()
    if not paths:
        print(json.dumps({
            "status": "source_not_found",
            "artifact": f"llm_inputs/{ARTIFACT}",
            "checked_paths": sorted(set(checked)),
            "finding": "The specified archived artifact was not found as a readable file; prior request details remain unknown."
        }, ensure_ascii=False))
        return

    reports = []
    for path in paths:
        try:
            with open(path, "r", encoding="utf-8") as stream:
                document = json.load(stream)
        except (OSError, UnicodeError, json.JSONDecodeError) as exc:
            reports.append({"path": path, "status": "read_or_parse_error", "error": str(exc)})
            continue

        matches = []
        for record_path, record in walk_records(document):
            text = json.dumps(record, ensure_ascii=False, sort_keys=True)
            lowered = text.lower()
            if "192.168.5.4" in text and ("traversal" in lowered or "flag.txt" in lowered):
                matches.append({"source_path": record_path, "record": record})
        reports.append({
            "path": path,
            "status": "parsed",
            "top_level_type": type(document).__name__,
            "matching_record_count": len(matches),
            "matching_records": matches
        })

    print(json.dumps({
        "status": "inspected",
        "artifact": f"llm_inputs/{ARTIFACT}",
        "reports": reports,
        "coverage_note": "Only archived records matching the in-scope target and traversal or flag-path terms are selected. Missing or partial records do not establish omitted request details."
    }, ensure_ascii=False))


if __name__ == "__main__":
    main()

