            checks.append({"path": path, "result": "readable_regular_file"})
            break
        checks.append({"path": path, "result": "not_a_readable_regular_file"})
    except OSError as exc:
        checks.append({"path": path, "result": "error", "error": str(exc)})

if found is None:
