def walk(value, path="$", ancestors=()):
    if isinstance(value, dict):
        serialized = json.dumps(value, ensure_ascii=False, sort_keys=True)
        lowered = serialized.lower()
        relevant = "flag.txt" in lowered and any(term in lowered for term in terms[1:])
        if relevant:
            records.append({"json_path": path, "record": value})
        for key, child in value.items():
            walk(child, path + "[" + json.dumps(str(key), ensure_ascii=False) + "]", ancestors + (value,))
    elif isinstance(value, list):
        for index, child in enumerate(value):
            walk(child, path + "[" + str(index) + "]", ancestors)

walk(data)

