import json
import os
import re
import sys
from pathlib import Path

ARTIFACT = "db6a88fac86c20e869965bed1e82aad0e12d5ea2f6a248e5583e817fa4837ea7.json"
RELATIVE = Path("llm_inputs") / ARTIFACT


def discover():
    found = []
    checked = []
    direct = [Path.cwd() / RELATIVE, Path("/root/scripts") / RELATIVE,
              Path("/root") / RELATIVE, Path("/") / RELATIVE,
              Path("/workspace") / RELATIVE, Path("/app") / RELATIVE]
    seen = set()
    for path in direct:
        key = str(path)
        if key in seen:
            continue
        seen.add(key)
        try:
            if path.is_file() and os.access(path, os.R_OK):
                found.append(path.resolve())
            else:
                checked.append({"path": key, "result": "not_a_readable_regular_file"})
        except OSError as exc:
            checked.append({"path": key, "result": "access_error", "error": str(exc)})

    roots = [Path.cwd(), Path("/root"), Path("/workspace"), Path("/app"),
             Path("/tmp"), Path("/mnt"), Path("/home"), Path("/var/tmp")]
    visited_dirs = set()
    for root in roots:
        try:
            root = root.resolve()
        except OSError:
            continue
        if not root.is_dir() or str(root) in visited_dirs:
            continue
        visited_dirs.add(str(root))
        for current, dirs, files in os.walk(root, topdown=True, onerror=lambda _e: None):
            dirs[:] = [d for d in dirs if d not in {"proc", "sys", "dev", ".git", "node_modules"}]
            if ARTIFACT in files:
                candidate = Path(current) / ARTIFACT
                try:
                    if candidate.is_file() and os.access(candidate, os.R_OK):
                        found.append(candidate.resolve())
                except OSError:
                    pass
    unique = []
    for path in found:
        if path not in unique:
            unique.append(path)
    return unique, checked


def extract_relevant(data):
    records = []
    leaves = []
    seen_records = set()
    markers = re.compile(r"apache|travers|flag\.txt|%2e|\.\./|%252e|request|response", re.I)
    request_key = re.compile(r"request|url|uri|path|target|command|response|outcome|status", re.I)

    def walk(value, path):
        if isinstance(value, dict):
            compact = json.dumps(value, ensure_ascii=False, separators=(",", ":"))
            has_request_field = any(request_key.search(str(k)) for k in value)
            if has_request_field and markers.search(compact):
                key = compact
                if key not in seen_records:
                    records.append({"source_path": path, "record": value})
                    seen_records.add(key)
            for key, child in value.items():
                walk(child, path + "[" + json.dumps(str(key), ensure_ascii=False) + "]")
        elif isinstance(value, list):
            for index, child in enumerate(value):
                walk(child, path + "[" + str(index) + "]")
        elif isinstance(value, str) and markers.search(value):
            leaves.append({"source_path": path, "text": value})

    walk(data, "$artifact")
    return records, leaves


def main():
    paths, checked = discover()
    report = {"artifact": str(RELATIVE), "located_paths": [str(p) for p in paths],
              "checked_paths": checked, "status": "source_not_found"}
    if paths:
        path = paths[0]
        report["selected_path"] = str(path)
        try:
            raw = path.read_bytes()
            report["sha256"] = __import__("hashlib").sha256(raw).hexdigest()
            try:
                data = json.loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                report.update({"status": "read_but_parse_failed", "error": str(exc),
                               "size_bytes": len(raw)})
            else:
                records, leaves = extract_relevant(data)
                report.update({"status": "read_and_parsed", "size_bytes": len(raw),
                               "top_level_type": type(data).__name__,
                               "relevant_records": records,
                               "relevant_text_leaves": leaves})
        except OSError as exc:
            report.update({"status": "read_error", "error": str(exc)})
    print(json.dumps(report, ensure_ascii=False))


if __name__ == "__main__":
    main()

