import json
import os
import sys
from pathlib import Path

ARTIFACT = "afebeddbb82e505fe3fdbc8324e0bd264a7f69db8f42c62ac4c1b3e46a5e982c.json"
SEARCH_ROOTS = [
    Path("/root/scripts/llm_inputs"),
    Path("/root/llm_inputs"),
    Path("/llm_inputs"),
    Path("/workspace/llm_inputs"),
    Path("/app/llm_inputs"),
    Path("/tmp/llm_inputs"),
    Path("/root"),
    Path("/workspace"),
    Path("/app"),
    Path("/tmp"),
]


def locate_exact_artifact():
    found = []
    checked_roots = []
    errors = []
    seen = set()

    for root in SEARCH_ROOTS:
        if not root.is_dir():
            checked_roots.append({"path": str(root), "result": "not_a_directory"})
            continue
        checked_roots.append({"path": str(root), "result": "searched"})
        # Search for the exact requested basename only; do not substitute another ID.
        for current, dirs, files in os.walk(root, followlinks=False):
            dirs[:] = sorted(d for d in dirs if d not in {"proc", "sys", "dev"})
            if ARTIFACT in files:
                candidate = Path(current) / ARTIFACT
                try:
                    resolved = candidate.resolve(strict=True)
                except OSError as exc:
                    errors.append({"path": str(candidate), "error": str(exc)})
                    continue
                key = str(resolved)
                if key not in seen:
                    seen.add(key)
                    found.append(resolved)
    return found, checked_roots, errors


def relevant_material(data):
    records = []
    traversal_markers = ("traversal", "%2e", "%252e", "..", "flag.txt")
    request_markers = ("request", "url", "path", "apache", "response", "outcome")

    def walk(value, location):
        if isinstance(value, dict):
            try:
                encoded = json.dumps(value, ensure_ascii=False, sort_keys=True)
            except (TypeError, ValueError):
                encoded = repr(value)
            lower = encoded.lower()
            has_traversal_detail = any(marker in lower for marker in traversal_markers)
            has_request_context = any(marker in lower for marker in request_markers)
            if has_traversal_detail and has_request_context:
                records.append({"source_location": location, "record": value})
                # Keep the enclosing relevant record intact rather than emitting
                # redundant copies of every nested field.
                return
            for key, child in value.items():
                walk(child, location + "." + str(key))
        elif isinstance(value, list):
            for index, child in enumerate(value):
                walk(child, location + "[" + str(index) + "]")
        elif isinstance(value, str):
            lower = value.lower()
            if any(marker in lower for marker in traversal_markers) and any(
                marker in lower for marker in request_markers
            ):
                records.append({"source_location": location, "text": value})

    walk(data, "$" )
    return records


def main():
    paths, checked_roots, search_errors = locate_exact_artifact()
    result = {
        "requested_artifact": ARTIFACT,
        "checked_roots": checked_roots,
        "search_errors": search_errors,
        "sources": [],
    }

    if not paths:
        result["status"] = "source_not_found"
        result["note"] = "The exact metadata-identified artifact was not found in the searched roots. No other artifact ID was substituted."
    else:
        for path in paths:
            source = {"path": str(path)}
            try:
                if not path.is_file() or not os.access(path, os.R_OK):
                    source["status"] = "not_a_readable_regular_file"
                else:
                    raw = path.read_bytes()
                    source["size_bytes"] = len(raw)
                    try:
                        data = json.loads(raw.decode("utf-8"))
                    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                        source["status"] = "readable_but_not_valid_utf8_json"
                        source["parse_error"] = str(exc)
                    else:
                        source["status"] = "parsed"
                        source["relevant_traversal_material"] = relevant_material(data)
                        source["relevant_record_count"] = len(source["relevant_traversal_material"])
            except OSError as exc:
                source["status"] = "read_error"
                source["error"] = str(exc)
            result["sources"].append(source)
        result["status"] = "inspected"

    print(json.dumps(result, ensure_ascii=False, sort_keys=True))


if __name__ == "__main__":
    main()

