import hashlib
import json
import os
import sys

TARGET = "f6a4ce6e4e8c7f7ba03d3d3e8f86f9d5c85ff01664e8e4728b9ce381d04e5a9e.json"
SKIP = {"/proc", "/sys", "/dev"}
found = []
errors = []
checked_roots = []

# Search the runtime filesystem for this exact metadata-identified basename only.
for root in ["/", os.getcwd()]:
    root = os.path.abspath(root)
    if root in checked_roots or not os.path.isdir(root):
        continue
    checked_roots.append(root)
    for current, dirs, files in os.walk(root, followlinks=False, onerror=lambda e: errors.append({"path": getattr(e, "filename", None), "error": str(e)})):
        dirs[:] = [d for d in dirs if os.path.join(current, d) not in SKIP]
        if TARGET in files:
            found.append(os.path.join(current, TARGET))

results = []
for path in found:
    try:
        with open(path, "rb") as f:
            raw = f.read()
        item = {
            "path": path,
            "sha256": hashlib.sha256(raw).hexdigest(),
            "bytes": len(raw),
        }
        try:
            item["json_parse"] = "parsed"
            item["content"] = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as e:
            item["json_parse"] = "failed"
            item["parse_error"] = str(e)
            item["raw_text"] = raw.decode("utf-8", errors="replace")
        results.append(item)
    except OSError as e:
        results.append({"path": path, "read_error": str(e)})

print(json.dumps({
    "requested_artifact": TARGET,
    "status": "found" if results else "source_not_found",
    "searched_roots": checked_roots,
    "search_errors": errors,
    "sources": results,
}, ensure_ascii=False))
